        dialogue: [['Jon', 'Antall kveldsreiser økte etter at biblioteket utvidet åpningstiden.', 'Numărul călătoriilor de seară a crescut după prelungirea programului bibliotecii.'], ['Mara', 'Det kan tyde på en sammenheng, men hva annet skjedde?', 'Aceasta poate indica o legătură, dar ce altceva s-a întâmplat?'], ['Jon', 'Økningen sammenfalt med skolestarten.', 'Creșterea a coincis cu începutul școlii.'], ['Mara', 'Da må anslaget ta høyde for flere mulige forklaringer.', 'Atunci estimarea trebuie să ia în calcul mai multe explicații posibile.'], ['Jon', 'Jeg skriver en tendens, ikke en sikker virkning.', 'Voi scrie o tendință, nu un efect sigur.'], ['Mara', 'Og oppgi usikkerhetsmarginen dersom den er beregnet.', 'Și menționează marja de incertitudine, dacă a fost calculată.']],
        grammar: { title: 'Modalizare prudentă a concluziilor', rule: '„Kan tyde på” marchează un indiciu. „Skyldes” afirmă o cauză mai direct. „Etter at” indică ordinea temporală și nu dovedește cauza. Alege expresia după ceea ce permit datele.', examples: ['Økningen kan tyde på større etterspørsel. — Creșterea poate indica o cerere mai mare.', 'Økningen kom etter at rutetiden ble endret. — Creșterea a venit după schimbarea orarului.'], wrong: 'Reisene økte etter skolestart, derfor beviser dette at biblioteket er årsaken.' },
        choice: ['Care formulare respectă limita observației?', ['Biblioteket forårsaket hele økningen.', 'Økningen kan tyde på større behov, men andre forhold kan spille inn.', 'Tallene gjør andre forklaringer umulige.'], 1, 'Formularea recunoaște indiciul și păstrează deschise explicațiile alternative.'],
