      vocabulary: [['selvstendig dømmekraft', 'judecată independentă', 'Selvstendig dømmekraft innebærer å vurdere grunnlaget, ikke bare velge side.', 'Judecata independentă presupune evaluarea bazei, nu doar alegerea unei tabere.'], ['en begrunnet posisjon', 'o poziție argumentată', 'En begrunnet posisjon kan være tydelig uten å være skråsikker.', 'O poziție argumentată poate fi clară fără să fie categorică excesiv.'], ['en sporbar vurdering', 'o evaluare cu raționament urmăribil', 'Leseren trenger en sporbar vurdering av kildene.', 'Cititorul are nevoie de o evaluare a surselor al cărei raționament poate fi urmărit.'], ['et refleksjonsnotat', 'o notă de reflecție', 'Refleksjonsnotatet forklarer hvorfor teksten ble endret.', 'Nota de reflecție explică de ce a fost modificat textul.'], ['å integrere', 'a integra', 'Vi integrerer kritikken i argumentasjonen.', 'Integrăm critica în argumentare.'], ['et forbehold av betydning', 'o rezervă importantă', 'Et forbehold av betydning må også være med i kortversjonen.', 'O rezervă importantă trebuie păstrată și în versiunea scurtă.']],
      dialogue: [['Mara', 'Porteføljen skal ikke bare vise den peneste sluttversjonen.', 'Portofoliul nu trebuie să arate doar cea mai frumoasă versiune finală.'], ['Jon', 'Den skal også vise en sporbar vurdering av kilder og innvendinger.', 'Trebuie să arate și o evaluare urmăribilă a surselor și obiecțiilor.'], ['Mara', 'I refleksjonsnotatet forklarer jeg hvorfor anbefalingen ble avgrenset.', 'În nota de reflecție explic de ce a fost delimitată recomandarea.'], ['Jon', 'Og hvilke forbehold av betydning som må følge presentasjonen.', 'Și ce rezerve importante trebuie să însoțească prezentarea.'], ['Mara', 'Da blir selvstendig dømmekraft synlig som arbeid, ikke som selvsikker tone.', 'Atunci judecata independentă devine vizibilă ca muncă, nu ca ton sigur pe sine.'], ['Jon', 'Det gir publikum mulighet til å vurdere både posisjonen og veien dit.', 'Aceasta oferă publicului posibilitatea să evalueze atât poziția, cât și drumul până la ea.']],
      grammar: { title: 'Poziție clară cu limite verificabile', rule: '„Jeg fastholder …, men reviderer …” poate diferenția ce rămâne de ce se schimbă. „På det foreliggende grunnlaget” limitează evaluarea la informația disponibilă. Precizia avansată cere și fluență, și trasabilitatea responsabilității.', examples: ['Jeg fastholder målet, men reviderer anbefalingen om gjennomføring. — Mențin obiectivul, dar revizuiesc recomandarea despre realizare.', 'På det foreliggende grunnlaget anbefaler jeg en avgrenset prøveperiode. — Pe baza disponibilă recomand o perioadă de probă limitată.'], wrong: 'Jeg er sikker, så kildene og forbeholdene trenger ikke forklares.' },
